UPDATE companies
name = #{company.name}, currency_center_id = #{company.baseCurrencyId}, vat_number = #{company.vatNo}, business_number = #{company.officeTelephone}, other_number = #{company.otherTelephone}, fax_number = #{company.faxNumber}, email_address = #{company.email}, address = #{company.address}, address_kh = #{company.addressInKhmer}, photo = #{company.photo}, is_active = #{company.isActive}, modified = NOW(), modified_by = #{company.modifiedBy}
WHERE id = #{company.id}

UPDATE companies
SET is_active   = 2,
    modified    = NOW(),
    modified_by = #{userId}
WHERE id = #{id};
